let providerLookupTimer;
async function discoverMailProvider(email, prefix) {
  if (!email.includes('@')) return;
  if (window.mailaiMailLogin?.manualServers(prefix)) return;
  const input = document.getElementById(`${prefix}-user`);
  const selection = window.mailaiMailLogin?.selection(prefix) || '';
  try {
    const profile = window.mailaiMailLogin?.profile(prefix) || await api(`/api/system/mail/discover?email=${encodeURIComponent(email)}`);
    if (input.value.trim() !== email || (window.mailaiMailLogin?.selection(prefix) || '') !== selection || window.mailaiMailLogin?.manualServers(prefix)) return;
    document.getElementById(`${prefix}-host`).value = profile.imap_host;
    document.getElementById(`${prefix}-port`).value = profile.imap_port;
    document.getElementById(`${prefix}-smtp-host`).value = profile.smtp_host;
    document.getElementById(`${prefix}-smtp-port`).value = profile.smtp_port;
    const smtpSsl = document.getElementById(`${prefix}-smtp-ssl`);
    const smtpStarttls = document.getElementById(`${prefix}-smtp-starttls`);
    if (smtpSsl) smtpSsl.checked = profile.smtp_ssl;
    if (smtpStarttls) smtpStarttls.checked = profile.smtp_starttls;
    const hint = document.getElementById(`${prefix}-provider-hint`);
    mailaiBindUI(hint, "textContent", () => (profile.detected
      ? mailaiTemplate`已识别为 ${profile.provider} · 将同时验证收件与发件服务`
      : mailaiText('未收录该服务商，已按域名推测服务器；连接失败时可展开高级设置修改')));
    hint.classList.toggle('manual', !profile.detected);
  } catch (_) {}
}

['onboarding', 'mail'].forEach(prefix => {
  document.getElementById(`${prefix}-user`).addEventListener('input', event => {
    clearTimeout(providerLookupTimer);
    providerLookupTimer = setTimeout(() => discoverMailProvider(event.target.value.trim(), prefix), 260);
  });
});

// macOS 可强制常驻原生滚动槽；三栏改用不受系统设置影响的悬浮圆角指示器。
const MAIN_SCROLL_SELECTOR = '.sidebar, .email-list, .reading-pane';
const scrollIndicators = new WeakMap();
const scrollTimers = new WeakMap();

function ensureScrollIndicator(target) {
  let indicator = scrollIndicators.get(target);
  if (indicator) return indicator;
  indicator = document.createElement('span');
  indicator.className = 'mailai-scroll-indicator';
  indicator.setAttribute('aria-hidden', 'true');
  indicator.innerHTML = '<i></i>';
  document.body.appendChild(indicator);
  scrollIndicators.set(target, indicator);
  return indicator;
}

function syncScrollIndicator(target) {
  const indicator = ensureScrollIndicator(target);
  const rect = target.getBoundingClientRect();
  const overflow = target.scrollHeight - target.clientHeight;
  const inset = window.innerWidth <= 760 ? 9 : 13;
  const trackHeight = Math.max(0, rect.height - inset * 2);
  if (overflow <= 1 || trackHeight < 34 || rect.width <= 0 || rect.height <= 0) {
    indicator.hidden = true;
    indicator.classList.remove('is-visible');
    return;
  }
  indicator.hidden = false;
  indicator.style.left = `${Math.round(rect.right - (window.innerWidth <= 760 ? 7 : 9))}px`;
  indicator.style.top = `${Math.round(rect.top + inset)}px`;
  indicator.style.height = `${Math.round(trackHeight)}px`;
  const thumb = indicator.firstElementChild;
  const thumbHeight = Math.min(trackHeight, Math.max(34, trackHeight * target.clientHeight / target.scrollHeight));
  const travel = trackHeight - thumbHeight;
  const offset = travel * Math.min(1, Math.max(0, target.scrollTop / overflow));
  thumb.style.height = `${Math.round(thumbHeight)}px`;
  thumb.style.transform = `translateY(${Math.round(offset)}px)`;
}

function showScrollIndicator(target) {
  syncScrollIndicator(target);
  const indicator = scrollIndicators.get(target);
  if (!indicator || indicator.hidden) return;
  indicator.classList.add('is-visible');
  clearTimeout(scrollTimers.get(target));
  scrollTimers.set(target, setTimeout(() => {
    indicator.classList.remove('is-visible');
    scrollTimers.delete(target);
  }, 520));
}

function initMainScrollIndicators() {
  const targets = [...document.querySelectorAll(MAIN_SCROLL_SELECTOR)];
  targets.forEach(target => {
    syncScrollIndicator(target);
    target.addEventListener('scroll', () => showScrollIndicator(target), {passive:true});
  });
  const syncAll = () => targets.forEach(syncScrollIndicator);
  window.addEventListener('resize', syncAll, {passive:true});
  if ('ResizeObserver' in window) {
    const observer = new ResizeObserver(syncAll);
    targets.forEach(target => observer.observe(target));
  }
}

initMainScrollIndicators();

function hideAppPreloader() {
  const preloader = document.getElementById('app-preloader');
  if (!preloader || preloader.dataset.handoff === 'running' || preloader.classList.contains('leaving')) return;
  const source = preloader.querySelector('.preloader-companion');
  const target = document.querySelector('#assistant-orb .companion-art');
  const sourceBrand = preloader.querySelector('.preloader-brand');
  const targetBrand = document.querySelector('.topbar .brand');
  const onboarding = document.getElementById('onboarding-overlay');
  const reducedMotion = matchMedia('(prefers-reduced-motion: reduce)').matches || document.body.classList.contains('companion-still');
  const introRemaining = Number(preloader.dataset.introUntil || 0) - performance.now();
  if (!reducedMotion && introRemaining > 0) {
    if (!preloader._introTimer) {
      preloader._introTimer = setTimeout(() => {
        preloader._introTimer = null;
        hideAppPreloader();
      }, introRemaining + 16);
    }
    return;
  }
  clearTimeout(preloader._introTimer);
  const animations = [];
  let routeFrame = 0;
  const duration = reducedMotion ? 180 : 1800;
  preloader.style.setProperty('--handoff-duration', duration + 'ms');
  preloader.dataset.handoff = 'running';
  // Confirm that the workspace is ready, not that remote mail sync succeeded.
  preloader.classList.add('completion-confirmed');
  const readyLabel = preloader.querySelector('.preloader-status span');
  const readyHint = preloader.querySelector('.preloader-status small');
  if (readyLabel) {
    readyLabel.removeAttribute('data-i18n');
    mailaiBindUI(readyLabel, "textContent", () => (document.documentElement.lang.startsWith('en') ? 'Workspace ready' : mailaiText('工作台已就绪')));
  }
  if (readyHint) {
    readyHint.removeAttribute('data-i18n');
    mailaiBindUI(readyHint, "textContent", () => (document.documentElement.lang.startsWith('en') ? 'Welcome to MailAI' : mailaiText('欢迎使用 MailAI')));
  }
  // One continuous contour becomes the reading pane's lower edge. Interpolate
  // SVG coordinates directly: CSS path interpolation is not uniform in WebKit.
  const route = preloader.querySelector('.preloader-route');
  const routeSvg = route?.querySelector('svg');
  const routePath = route?.querySelector('path');
  const readingPane = document.querySelector('.layout > .reading-pane');
  if (!reducedMotion && routePath && routeSvg && readingPane && onboarding?.classList.contains('hidden')) {
    const lane = routeSvg.getBoundingClientRect();
    const pane = readingPane.getBoundingClientRect();
    if (lane.width > 0 && pane.width > 0 && pane.height > 0) {
      const zoom = Number(getComputedStyle(document.body).zoom) || 1;
      const x = value => (value - lane.left) / lane.width * 1000;
      const left = x(pane.left + 1), right = x(pane.right - 1);
      const radius = Math.min((parseFloat(getComputedStyle(readingPane).borderBottomLeftRadius) || 0) * zoom, pane.width / 4);
      const r = radius / lane.width * 1000;
      const targetD = `M${left} 38H${left}C${left} 52 ${left+r*.42} 62 ${left+r} 62H${right-r}C${right-r*.42} 62 ${right} 52 ${right} 38H${right}`;
      const sourceD = routePath.getAttribute('d');
      const numbers = /-?\d*\.?\d+/g;
      const from = sourceD.match(numbers).map(Number);
      const to = targetD.match(numbers).map(Number);
      if (from.length === to.length) {
        const started = performance.now();
        const draw = now => {
          const t = Math.min(1, (now-started)/1100);
          const eased = t*t*(3-2*t);
          let index = 0;
          routePath.setAttribute('d', sourceD.replace(numbers, () => {
            const i = index++;
            return (from[i] + (to[i]-from[i])*eased).toFixed(3);
          }));
          if (t < 1 && preloader.isConnected) routeFrame = requestAnimationFrame(draw);
        };
        routeFrame = requestAnimationFrame(draw);
        const dy = (pane.bottom - 1 - (lane.top + lane.height * 62/80)) / zoom;
        animations.push(route.animate([
          {transform:'translate3d(0,0,0)'},
          {transform:`translate3d(0,${dy}px,0)`},
        ], {duration:1100,easing:'cubic-bezier(.42,0,.22,1)',fill:'both'}));
        animations.push(route.animate([
          {opacity:1},{opacity:.72,offset:.5},{opacity:.36,offset:.8},{opacity:0},
        ], {duration:1550,easing:'linear',fill:'both'}));
      }
    }
  }
  // Derive both destinations from the live workspace. The mascot travels by
  // its grounded center point, so resizing it never introduces a visual jump.
  if (!reducedMotion && source && target && onboarding?.classList.contains('hidden')) {
    const from = source.getBoundingClientRect();
    const to = target.getBoundingClientRect();
    const zoom = Number(getComputedStyle(document.body).zoom) || 1;
    Object.assign(source.style, {
      left:`${from.left / zoom}px`, top:`${from.top / zoom}px`, bottom:'auto',
      width:`${from.width / zoom}px`, height:`${from.height / zoom}px`, transform:'none',
    });
    const dx = (to.left + to.width / 2 - (from.left + from.width / 2)) / zoom;
    const dy = (to.bottom - from.bottom) / zoom;
    const scale = to.width / from.width;
    animations.push(source.animate([
      {offset:0,transform:'translate3d(0,0,0) scale(1)',opacity:1},
      {offset:1,transform:`translate3d(${dx}px,${dy}px,0) scale(${scale})`,opacity:1},
    ], {duration:duration-180,easing:'cubic-bezier(.42,0,.24,1)',fill:'both'}));
    // Cross-fade only once both rigs occupy the same rectangle.
    animations.push(source.animate([{opacity:1},{opacity:0}], {
      delay:duration-180,duration:180,easing:'linear',fill:'forwards',
    }));
    setTimeout(() => {
      const parts = [...source.querySelectorAll('.companion-torso,.companion-foot-left,.companion-foot-right,.companion-arm-left,.companion-wave,.companion-leaves,.companion-bag')];
      const poses = parts.map(part => getComputedStyle(part).transform);
      source.classList.add('arriving');
      parts.forEach((part, index) => animations.push(part.animate([
        {transform:poses[index]}, {transform:'none'},
      ], {duration:300,easing:'ease-out',fill:'both'})));
    }, duration - 330);
    animations.push(target.animate([
      {opacity:0}, {opacity:0,offset:.9}, {opacity:1},
    ], {duration,easing:'linear',fill:'both'}));
    source.getBoundingClientRect();
    preloader.classList.add('handoff-active');
  }
  if (!reducedMotion && sourceBrand && targetBrand && onboarding?.classList.contains('hidden')) {
    const zoom = Number(getComputedStyle(document.body).zoom) || 1;
    // Match each element instead of scaling the whole lockup: the workspace
    // has its own icon size, text baseline and responsive subtitle visibility.
    for (const selector of ['img','strong','small']) {
      const start = sourceBrand.querySelector(selector);
      const end = targetBrand.querySelector(selector);
      if (!start || !end) continue;
      const from = start.getBoundingClientRect();
      const to = end.getBoundingClientRect();
      if (!from.width || !to.width) continue;
      start.style.transformOrigin = '0 0';
      animations.push(start.animate([
        {transform:'translate3d(0,0,0) scale(1,1)'},
        {transform:`translate3d(${(to.left-from.left)/zoom}px,${(to.top-from.top)/zoom}px,0) scale(${to.width/from.width},${to.height/from.height})`},
      ], {duration:1100,easing:'cubic-bezier(.42,0,.22,1)',fill:'both'}));
    }
    animations.push(sourceBrand.animate([
      {opacity:1},{opacity:1,offset:1100/duration},{opacity:0,offset:1300/duration},{opacity:0},
    ], {duration,fill:'both'}));
    animations.push(targetBrand.animate([
      {opacity:0}, {opacity:0,offset:1100/duration}, {opacity:1,offset:1300/duration}, {opacity:1},
    ], {duration,easing:'linear',fill:'both'}));
  }
  requestAnimationFrame(() => preloader.classList.add('leaving'));
  setTimeout(() => {
    cancelAnimationFrame(routeFrame);
    preloader.remove();
    animations.forEach(animation => animation.cancel());
  }, duration + 40);
}

// ===== 三栏宽度拖拽与本地记忆 =====
const PANE_SIZE_KEY = 'mailai.workspace.paneSizes.v1';
const PANE_DEFAULTS = {sidebar: 226, list: 405};

function readPaneSizes() {
  try { return {...PANE_DEFAULTS, ...JSON.parse(localStorage.getItem(PANE_SIZE_KEY) || '{}')}; }
  catch (_) { return {...PANE_DEFAULTS}; }
}

function constrainPaneSizes(input) {
  const layout = document.querySelector('.layout');
  const total = layout?.clientWidth || window.innerWidth;
  const readingMin = Math.min(440, Math.max(360, total * .32));
  let sidebar = Math.max(180, Math.min(380, Number(input.sidebar) || PANE_DEFAULTS.sidebar));
  let list = Math.max(300, Math.min(720, Number(input.list) || PANE_DEFAULTS.list));
  const available = Math.max(480, total - 24 - readingMin);
  if (sidebar + list > available) list = Math.max(300, available - sidebar);
  if (sidebar + list > available) sidebar = Math.max(180, available - list);
  return {sidebar:Math.round(sidebar), list:Math.round(list)};
}

function applyPaneSizes(sizes, persist = false) {
  const layout = document.querySelector('.layout');
  if (!layout) return;
  const value = constrainPaneSizes(sizes);
  layout.style.setProperty('--sidebar-width', value.sidebar + 'px');
  layout.style.setProperty('--list-width', value.list + 'px');
  document.querySelector('[data-resizer="sidebar"]')?.setAttribute('aria-valuenow', value.sidebar);
  document.querySelector('[data-resizer="list"]')?.setAttribute('aria-valuenow', value.list);
  if (persist) localStorage.setItem(PANE_SIZE_KEY, JSON.stringify(value));
  return value;
}

function initPaneResizers() {
  let sizes = applyPaneSizes(readPaneSizes());
  document.querySelectorAll('.pane-resizer').forEach(handle => {
    const kind = handle.dataset.resizer;
    handle.setAttribute('aria-valuemin', kind === 'sidebar' ? '180' : '300');
    handle.setAttribute('aria-valuemax', kind === 'sidebar' ? '380' : '720');
    handle.addEventListener('pointerdown', event => {
      if (window.innerWidth <= 1024) return;
      event.preventDefault();
      const startX = event.clientX;
      const start = {...sizes};
      handle.setPointerCapture(event.pointerId);
      handle.classList.add('dragging'); document.body.classList.add('pane-resizing');
      const move = moveEvent => {
        const delta = moveEvent.clientX - startX;
        sizes = applyPaneSizes({...start, [kind]:start[kind] + delta});
      };
      const end = () => {
        handle.removeEventListener('pointermove', move);
        handle.classList.remove('dragging'); document.body.classList.remove('pane-resizing');
        sizes = applyPaneSizes(sizes, true);
      };
      handle.addEventListener('pointermove', move);
      handle.addEventListener('pointerup', end, {once:true});
      handle.addEventListener('pointercancel', end, {once:true});
    });
    handle.addEventListener('dblclick', () => { sizes = applyPaneSizes(PANE_DEFAULTS, true); toast(mailaiText('已恢复默认栏宽'), 'success'); });
    handle.addEventListener('keydown', event => {
      if (!['ArrowLeft','ArrowRight'].includes(event.key)) return;
      event.preventDefault();
      sizes = applyPaneSizes({...sizes, [kind]:sizes[kind] + (event.key === 'ArrowRight' ? 16 : -16)}, true);
    });
  });
  window.addEventListener('resize', () => { sizes = applyPaneSizes(sizes); });
}

initPaneResizers();

