          const missing = values.findIndex(value => !value);
          if (missing >= 0) { content.querySelector(`[data-document-value="${missing}"]`)?.focus(); throw new Error(mailaiText('请填写全部字段；不适用的项目可填“无”')); }
          mailaiBindUI(status, "textContent", () => (mailaiText('正在填写文件、回读核对并准备回复…')));
          const fields = c.plan.fields.map((field, index) => ({...field, value:values[index]}));
