  replay.innerHTML = `<svg viewBox="0 0 20 20" aria-hidden="true"><path d="M15.5 7.5A6 6 0 1 0 16 12M15.5 3.5v4h-4"/></svg><span data-i18n="guide.replay">重新体验引导</span>`;
